    screenShape: 'round',
    screenSize: 'regular',
    screenViewport: 'normal',
    view: 'home',
    heartRate: null,
    stress: null,
    heartRates: [],
    stresses: [],
    heartRateText: '--',
    stressText: '--',
    suggest: false,
    statusTitle: '正在感受你的节律',
    statusSubtitle: '保持自然，数据将很快出现',
    healthMessage: '',
    startedAt: 0,
    cycleStartElapsed: 0,
    currentPattern: steady.PATTERNS.standard,
    patternLabel: '标准节奏 · 4-2-4',
    breathPhase: 'inhale',
    phaseLabel: '慢慢吸气',
    remainingText: '60',
    timer: null,
    baseline: { heartRate: null, stress: null },
    resultHeartRateDetail: '',
    resultHeartRateDelta: '',
    resultStressDetail: '',
    resultStressDelta: '',
    heartRateImproved: false,
    stressImproved: false,
